const socket_group_fields = .{ "bun_connect_group_tcp", "bun_connect_group_tls", "spawn_ipc_group", "test_parallel_ipc_group", "postgres_group", "postgres_tls_group", "mysql_group", "mysql_tls_group", "valkey_group", "valkey_tls_group", "ws_upgrade_group", "ws_upgrade_tls_group", "ws_client_group", "ws_client_tls_group" };
const S = bun.MAX_PATH_BYTES;
pub const SmallBuf = [2 * S]u8;
pub const MediumBuf = [8 * S]u8;
pub const LargeBuf = [32 * S]u8;
pub const ProxySlot = struct {
